+        if (matcher.find()) {
+            int start = matcher.start();
+            try {
+                String tail = name.substring(start + 1);
+                return Optional.of(ModuleDescriptor.Version.parse(tail));
+            } catch (IllegalArgumentException ignore) {}
+        }
+        return Optional.empty();
+    }
