+                .stream()
+                .map(EmbeddedModulePath::dropCommentAndTrim)
+                .filter(Predicate.not(String::isEmpty))
+                .toList();
+            if (providerClasses.isEmpty() == false) {
+                map.put(sn, providerClasses);
+            }
+        }
