+        NativeMemoryCapacity currentScale = new NativeMemoryCapacity(
+            2 * TEST_JOB_SIZE - ByteSizeValue.ofMb(1).getBytes(),
+            2 * TEST_JOB_SIZE - ByteSizeValue.ofMb(1).getBytes()
+        );
