+                for (int i = 0; i < count; i++) {
+                    int fieldNumber = indexIn.readVInt();
+                    long fp = indexIn.readVLong();
+                    fieldToFileOffset.put(fieldNumber, fp);
+                }
+            } catch (Throwable t) {
